"""Rule system for Eleusis: LLM-generated rules and validation."""

import logging
import random
from dataclasses import dataclass

from eleusis.cards import Card, Suit
from eleusis.game_engine import Rule
from eleusis.llm_client import HuggingFaceClient, RefereeClient
from eleusis.prompts import get_rule_evaluation_prompt

logger = logging.getLogger(__name__)


@dataclass
class ValidationResult:
    """Result of rule validation."""

    valid: bool
    deterministic: bool
    works_with_empty_mainline: bool
    issues: list[str]


class LLMGeneratedRule(Rule):
    """Rule generated by an LLM, evaluated by the same LLM."""

    def __init__(
        self,
        rule_text: str,
        creator_client: HuggingFaceClient,
        model_name: str,
        code: str | None = None,
    ) -> None:
        """Initialize LLM-generated rule.

        Args:
            rule_text: Natural language description of the rule
            creator_client: LLM client used to create the rule
            model_name: Name of the model that created the rule
            code: Optional Python code implementation (not used yet, for future commits)
        """
        self.rule_text = rule_text
        self.creator_client = creator_client
        self.model_name = model_name
        self.code = code
        self.evaluation_cache: dict[str, bool] = {}

    def evaluate(self, card: Card, mainline: list[Card]) -> bool:
        """Evaluate if card is IN according to the rule by asking the creator LLM."""
        # Create cache key
        mainline_key = ",".join([str(c) for c in mainline])
        cache_key = f"{card}|{mainline_key}"

        # Check cache
        if cache_key in self.evaluation_cache:
            return self.evaluation_cache[cache_key]

        # Ask LLM to evaluate
        card_dict = card.to_dict()
        mainline_compact = " ".join([str(c) for c in mainline]) if mainline else "(empty)"

        prompt = get_rule_evaluation_prompt(self.rule_text, card_dict, mainline_compact)

        try:
            response = self.creator_client.generate_structured(
                prompt, max_tokens=2048, xml_tag="EVALUATION"
            )
            result = response["result"].lower() == "in"

            # Cache result
            self.evaluation_cache[cache_key] = result
            return result

        except Exception as e:
            logger.error(f"Failed to evaluate card with LLM: {e}")
            # Fallback: reject card
            return False

    def description(self) -> str:
        """Return the rule description."""
        return self.rule_text


class RuleValidator:
    """Validates LLM-generated rules."""

    def __init__(self, referee_client: RefereeClient | None = None) -> None:
        """Initialize validator with optional referee client."""
        self.referee_client = referee_client

    def validate_rule(
        self, rule: LLMGeneratedRule, num_test_cases: int = 3
    ) -> ValidationResult:
        """Validate that a rule meets requirements."""
        issues = []

        # Test 1: Determinism - same input should give same output
        deterministic = self._test_determinism(rule)
        if not deterministic:
            issues.append("Rule is not deterministic")

        # Test 2: Empty mainline - rule must work with first card
        works_with_empty = self._test_empty_mainline(rule)
        if not works_with_empty:
            issues.append("Rule does not work with empty mainline")

        # Test 3: Run various test scenarios
        test_issues = self._run_test_scenarios(rule, num_test_cases)
        issues.extend(test_issues)

        valid = len(issues) == 0

        return ValidationResult(
            valid=valid,
            deterministic=deterministic,
            works_with_empty_mainline=works_with_empty,
            issues=issues,
        )

    def _test_determinism(self, rule: LLMGeneratedRule, num_tests: int = 3) -> bool:
        """Test if rule gives consistent results."""
        # Test a few random scenarios multiple times
        test_scenarios = [
            (Card(5, Suit.HEARTS), []),
            (Card(8, Suit.SPADES), [Card(5, Suit.HEARTS)]),
            (Card(2, Suit.DIAMONDS), [Card(5, Suit.HEARTS), Card(8, Suit.SPADES)]),
        ]

        for card, mainline in test_scenarios:
            # Evaluate same scenario multiple times
            results = []
            for _ in range(num_tests):
                result = rule.evaluate(card, mainline)
                results.append(result)

            # Check if all results are the same
            if len(set(results)) > 1:
                logger.warning(f"Non-deterministic results for {card} with mainline {mainline}")
                return False

        return True

    def _test_empty_mainline(self, rule: LLMGeneratedRule) -> bool:
        """Test if rule works with empty mainline."""
        try:
            # Try evaluating a few cards with empty mainline
            test_cards = [
                Card(1, Suit.HEARTS),
                Card(7, Suit.SPADES),
                Card(13, Suit.DIAMONDS),
            ]

            for card in test_cards:
                rule.evaluate(card, [])

            return True
        except Exception as e:
            logger.error(f"Rule failed with empty mainline: {e}")
            return False

    def _run_test_scenarios(
        self, rule: LLMGeneratedRule, num_tests: int
    ) -> list[str]:
        """Run random test scenarios to check rule behavior."""
        issues = []

        # Generate random scenarios
        for _ in range(num_tests):
            # Random mainline length 0-5
            mainline_length = random.randint(0, 5)
            mainline = []

            for _ in range(mainline_length):
                card = Card(random.randint(1, 13), random.choice(list(Suit)))
                mainline.append(card)

            # Random test card
            test_card = Card(random.randint(1, 13), random.choice(list(Suit)))

            try:
                rule.evaluate(test_card, mainline)
            except Exception as e:
                issues.append(f"Rule evaluation failed on random scenario: {e}")
                break

        return issues

    def check_equivalence(self, rule1_text: str, rule2_text: str) -> tuple[bool, str]:
        """Check if two rules are equivalent using referee LLM."""
        if not self.referee_client:
            raise ValueError("Referee client not configured")

        return self.referee_client.check_rule_equivalence(rule1_text, rule2_text)


# Predefined rules for testing and baselines
class AlternatingColorsRule(Rule):
    """Cards must alternate between red and black."""

    def evaluate(self, card: Card, mainline: list[Card]) -> bool:
        if not mainline:
            return True  # First card always accepted
        last_card = mainline[-1]
        return card.color != last_card.color

    def description(self) -> str:
        return "Cards must alternate between red and black colors"


class EvenRanksOnlyRule(Rule):
    """Only even-ranked cards are accepted."""

    def evaluate(self, card: Card, mainline: list[Card]) -> bool:
        return card.is_even

    def description(self) -> str:
        return "Only cards with even ranks (2, 4, 6, 8, 10, 12) are accepted"


class RankHigherThanLastRule(Rule):
    """Card rank must be higher than previous card."""

    def evaluate(self, card: Card, mainline: list[Card]) -> bool:
        if not mainline:
            return True
        last_card = mainline[-1]
        # Allow wrapping: any card can follow a King
        if last_card.rank == 13:
            return True
        return card.rank > last_card.rank

    def description(self) -> str:
        return "Card rank must be higher than the last mainline card (any card after King)"
